import type { PluginCreator } from 'postcss'
import {
  createNestedRuleContext,
  type NestedRuleWrap,
} from '../../../compiler-dom/src/htmlNesting'
import type { NestedNodeTypes } from '../../../compiler-dom/src/transforms/transformStyle'
import type {
  CombinatorTokens,
  DeepPseudoNames,
  DeprecatedDeepSyntax,
} from '../../../compiler-dom/src/parserOptions'

export class SlotPseudoNames {
  constructor(
    public slotted: string,
    public vSlotted: string,
  ) {}
}

export interface SelectorRewriteUnits {
  slots: SlotPseudoNames
  wrap: NestedRuleWrap
  nodeTypes: NestedNodeTypes
  deepSyntax: DeprecatedDeepSyntax
  tokens: CombinatorTokens
  deepPseudos: DeepPseudoNames
}

export function createSelectorRewriteUnits(): SelectorRewriteUnits {
  const nested = createNestedRuleContext()
  return {
    slots: new SlotPseudoNames(':slotted', '::v-slotted'),
    wrap: nested.wrap,
    nodeTypes: nested.nodeTypes,
    deepSyntax: nested.deepSyntax,
    tokens: nested.tokens,
    deepPseudos: nested.deepPseudos,
  }
}

export type {
  CombinatorTokens,
  DeepPseudoNames,
  DeprecatedDeepSyntax,
  NestedNodeTypes,
  NestedRuleWrap,
}

const trimPlugin: PluginCreator<{}> = () => {
  return {
    postcssPlugin: 'vue-sfc-trim',
    Once(root) {
      root.walk(({ type, raws }) => {
        if (type === 'rule' || type === 'atrule') {
          if (raws.before) raws.before = '\n'
          if ('after' in raws && raws.after) raws.after = '\n'
        }
      })
    },
  }
}

trimPlugin.postcss = true
export default trimPlugin

